type Store={data:AppData;setData:(updater:AppData|((prev:AppData)=>AppData))=>void;role:Role;setRole:(r:Role)=>void;logout:()=>void;reset:()=>void};
const navGroups=[
 {label:"",items:[{id:"dashboard",label:"Dashboard",icon:LayoutDashboard}]},
 {label:"Réservations",icon:CalendarDays,items:[{id:"reservations",label:"Toutes"},{id:"planning",label:"Planning / Calendrier"},{id:"confirm",label:"À confirmer"},{id:"preparation",label:"En préparation"},{id:"active",label:"En cours"},{id:"completed",label:"Terminées"},{id:"cancelled",label:"Annulées"}]},
 {label:"Flotte & Excursions",icon:Bike,items:[{id:"motos",label:"Motos"},{id:"circuits",label:"Circuits"},{id:"services",label:"Services"},{id:"maintenance",label:"Maintenance"}]},
 {label:"",items:[{id:"map",label:"Carte",icon:Map}]},
 {label:"Clients & Équipe",icon:Users,items:[{id:"clients",label:"Clients"},{id:"complaints",label:"Réclamations"},{id:"team",label:"Équipe"},{id:"users",label:"Utilisateurs"}]},
 {label:"Finance & Rapports",icon:WalletCards,items:[{id:"payments",label:"Paiements"},{id:"refunds",label:"Remboursements"},{id:"promotions",label:"Promotions"},{id:"reports",label:"Rapports"},{id:"activity",label:"Journal d’activité"}]},
] as const;
const labels:Record<Section,string>={dashboard:"Tableau de bord",reservations:"Toutes les réservations",planning:"Planning / Calendrier",confirm:"À confirmer",preparation:"En préparation",active:"En cours",completed:"Terminées",cancelled:"Annulées",motos:"Motos",circuits:"Circuits",services:"Services",maintenance:"Maintenance",map:"Carte opérationnelle",clients:"Clients",complaints:"Réclamations",team:"Équipe & guides",users:"Utilisateurs",payments:"Paiements",refunds:"Remboursements",promotions:"Promotions",reports:"Rapports",activity:"Journal d’activité"};
const statusTone=(s:string)=>/Payé|Disponible|Terminée|Confirmée|Actif|Validé|Résolu/.test(s)?"success":/Urgente|Échec|Hors|Annul|Ouvert/.test(s)?"danger":/attente|préparation|Maintenance|Planifiée|Réservée|Acompte|Partiellement/.test(s)?"warning":"info";
function Badge({children}:{children:ReactNode}){return <span className={`status ${statusTone(String(children))}`}>{children}</span>}
function IconButton({label,children,onClick}:{label:string;children:ReactNode;onClick?:()=>void}){return <Button variant="ghost" size="icon" aria-label={label} title={label} onClick={onClick}>{children}</Button>}
function PageTitle({eyebrow,title,description,action,onAction,settings}:{eyebrow:string;title:string;description:string;action?:string;onAction?:()=>void;settings?:()=>void}){return <div className="page-title"><div><span className="eyebrow">{eyebrow}</span><h1>{title}</h1><p>{description}</p></div><div className="page-actions">{settings&&<Button variant="outline" onClick={settings}><Settings2/>Paramètres</Button>}{action&&<Button onClick={onAction}><Plus/>{action}</Button>}</div></div>}
function Modal({title,children,onClose,wide=false}:{title:string;children:ReactNode;onClose:()=>void;wide?:boolean}){return <div className="modal-layer" role="dialog" aria-modal="true"><button className="modal-backdrop" aria-label="Fermer" onClick={onClose}/><div className={`modal-panel ${wide?"wide":""}`}><header><div><span className="eyebrow">TIZIFLOW OPS</span><h2>{title}</h2></div><IconButton label="Fermer" onClick={onClose}><X/></IconButton></header>{children}</div></div>}
function SettingsPanel({module,onClose}:{module:string;onClose:()=>void}){const groups:Record<string,string[]>={reservations:["Réservations le jour même","Statuts automatiques","Réservations manuelles"],motos:["Alerte batterie faible","Rappels de maintenance","Blocage autonomie critique"],circuits:["Afficher les tracés","Lissage GPS","Simulation GPS activée"],services:["Services réservables seuls","Capacité obligatoire","Tarification dynamique"],maintenance:["Rappels automatiques","Blocage immédiat de la moto","Photos obligatoires"],clients:["Préférences de communication","Téléphone obligatoire","Notes internes"],team:["Limiter les excursions par jour","Respecter les jours de repos","Bloquer les chevauchements"],users:["Invitation par e-mail","Expiration de session","Journaliser les exports"],payments:["Paiements en ligne","Paiements par carte","Paiements en espèces","Paiements partiels"]};const items=groups[module]??["Notifications internes","Exports autorisés","Historique détaillé"];return <Modal title={`Paramètres · ${labels[module as Section]??module}`} onClose={onClose}><div className="settings-list">{items.map((x,i)=><div key={x}><div><b>{x}</b><p>{i%2?"Appliqué à tous les nouveaux dossiers.":"Paramètre opérationnel modifiable par un administrateur."}</p></div><Switch defaultChecked={i!==2}/></div>)}</div><div className="form-grid"><label>Valeur par défaut<Input defaultValue={module==="payments"?"MAD":"30"}/></label><label>Délai / seuil<Input type="number" defaultValue={module==="motos"?20:24}/></label></div><div className="modal-actions"><Button variant="outline" onClick={onClose}>Annuler</Button><Button onClick={()=>{toast.success("Paramètres enregistrés");onClose()}}>Enregistrer</Button></div></Modal>}

export function MissionControl({store}:{store:Store}){const{data,setData,role,setRole,logout,reset}=store;const[section,setSectionState]=useState<Section>(()=>typeof window!=="undefined"?(new URLSearchParams(location.search).get("view") as Section)||"dashboard":"dashboard");const[mobileNav,setMobileNav]=useState(false);const[dark,setDark]=useState(false);const[search,setSearch]=useState("");const[modal,setModal]=useState<string|null>(null);const[selectedId,setSelectedId]=useState("");
 const setSection=(next:Section)=>{setSectionState(next);setMobileNav(false);history.replaceState({},"",`?view=${next}`)};
 useEffect(()=>{document.documentElement.classList.toggle("dark",dark)},[dark]);
 const results=useMemo(()=>{const q=search.trim().toLowerCase();if(!q)return[];const entries=[...data.reservations.map(x=>({type:"Réservation",id:x.id,label:`${x.id} · ${customerName(x.customerId,data)}`,go:"reservations" as Section})),...data.customers.map(x=>({type:"Client",id:x.id,label:`${x.firstName} ${x.lastName} · ${x.email}`,go:"clients" as Section})),...data.motorcycles.map(x=>({type:"Moto",id:x.id,label:`${x.id} · ${x.model}`,go:"motos" as Section})),...data.circuits.map(x=>({type:"Circuit",id:x.id,label:x.name,go:"circuits" as Section})),...data.guides.map(x=>({type:"Guide",id:x.id,label:x.name,go:"team" as Section})),...data.complaints.map(x=>({type:"Réclamation",id:x.id,label:`${x.id} · ${x.category}`,go:"complaints" as Section})),...data.payments.map(x=>({type:"Paiement",id:x.id,label:`${x.id} · ${x.reference}`,go:"payments" as Section})),...data.incidents.map(x=>({type:"Incident",id:x.id,label:`${x.id} · ${x.type}`,go:"map" as Section}))];return entries.filter(x=>x.label.toLowerCase().includes(q)).slice(0,12)},[search,data]);
 const openEntity=(go:Section,id:string)=>{setSelectedId(id);setSection(go);setSearch("")};
 return <div className="app-shell"><Environment compact/><Sidebar section={section} setSection={setSection} open={mobileNav} close={()=>setMobileNav(false)}/><div className="app-main"><header className="topbar"><IconButton label="Ouvrir le menu" onClick={()=>setMobileNav(true)}><Menu/></IconButton><div className="breadcrumb"><span>TiziFlow</span><ChevronRight/><b>{labels[section]}</b></div><div className="global-search"><Search/><Input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Rechercher réservation, client, moto…"/>{search&&<div className="search-results">{results.length?results.map(r=><Button variant="ghost" key={`${r.type}-${r.id}`} onClick={()=>openEntity(r.go,r.id)}><span>{r.type}</span><b>{r.label}</b><ChevronRight/></Button>):<p>Aucun résultat</p>}</div>}</div><Button className="quick-create" onClick={()=>setModal("quick")}><Plus/>Action rapide</Button><IconButton label="Notifications" onClick={()=>setModal("notifications")}><Bell/><i className="notification-dot"/></IconButton><IconButton label={dark?"Mode clair":"Mode sombre"} onClick={()=>setDark(!dark)}>{dark?<Sun/>:<Moon/>}</IconButton><div className="user-menu"><span>AT</span><div><b>Admin TiziFlow</b><small>{role}</small></div><ChevronDown/></div></header><main className="content"><SectionContent section={section} data={data} setData={setData} selectedId={selectedId} setSelectedId={setSelectedId} setSection={setSection} setModal={setModal}/></main></div>
 {modal==="quick"&&<QuickActions onClose={()=>setModal(null)} action={(s)=>{setModal(s);}}/>}
 {modal==="notifications"&&<Notifications onClose={()=>setModal(null)} data={data} go={setSection}/>} 
 {modal==="newReservation"&&<ReservationWizard data={data} setData={setData} onClose={()=>setModal(null)}/>} 
 {modal==="newCustomer"&&<SimpleCreate title="Nouveau client" fields={["Prénom","Nom","E-mail","Téléphone","Pays"]} onClose={()=>setModal(null)}/>} 
 {modal==="newMoto"&&<SimpleCreate title="Ajouter une moto" fields={["Marque","Modèle","Catégorie","Autonomie","Kilométrage"]} onClose={()=>setModal(null)}/>} 
 {modal==="newCircuit"&&<SimpleCreate title="Créer un circuit" fields={["Nom","Durée","Distance","Capacité","Prix"]} onClose={()=>setModal(null)}/>} 
 {modal==="newService"&&<SimpleCreate title="Ajouter un service" fields={["Nom","Prix","Durée","Capacité","Disponibilité"]} onClose={()=>setModal(null)}/>} 
 {modal==="payment"&&<PaymentModal data={data} setData={setData} onClose={()=>setModal(null)}/>} 
 {modal==="complaint"&&<SimpleCreate title="Créer une réclamation" fields={["Client","Réservation","Catégorie","Priorité","Description"]} onClose={()=>setModal(null)}/>} 
 {modal==="incident"&&<SimpleCreate title="Déclarer un incident" fields={["Type","Moto","Réservation","Lieu","Sévérité","Description"]} onClose={()=>setModal(null)}/>} 
 {modal?.startsWith("settings:")&&<SettingsPanel module={modal.split(":")[1]??""} onClose={()=>setModal(null)}/>} 
 {modal==="profile"&&<ProfileModal data={data} role={role} setRole={setRole} reset={reset} logout={logout} onClose={()=>setModal(null)}/>} 
 </div>}

function Sidebar({section,setSection,open,close}:{section:Section;setSection:(s:Section)=>void;open:boolean;close:()=>void}){return <><button className={`sidebar-scrim ${open?"open":""}`} aria-label="Fermer le menu" onClick={close}/><aside className={`sidebar ${open?"open":""}`}><div className="brand"><img src={logo} alt="TiziFlow"/><div><b>TiziFlow</b><span>MISSION CONTROL</span></div></div><div className="operations-pill"><span/><div><b>Opérations en direct</b><small>Midelt · Atlas</small></div></div><nav>{navGroups.map((g,gi)=><div className="nav-group" key={`${g.label}-${gi}`}>{g.label&&<div className="nav-heading">{g.icon&&<g.icon/>}<span>{g.label}</span></div>}{g.items.map(item=>{const Icon="icon" in item?item.icon:undefined;return <Button key={item.id} variant="ghost" className={section===item.id?"active":""} onClick={()=>setSection(item.id as Section)}>{Icon&&<Icon/>}<span>{item.label}</span>{item.id==="confirm"&&<i>5</i>}{item.id==="complaints"&&<i className="danger">3</i>}</Button>})}</div>)}</nav><button className="sidebar-user" onClick={()=>{window.dispatchEvent(new CustomEvent("tf-profile"))}}><span>AT</span><div><b>Admin TiziFlow</b><small>admin@tiziflow.ma</small></div><Settings2/></button></aside></>}

function SectionContent(p:{section:Section;data:AppData;setData:Store["setData"];selectedId:string;setSelectedId:(id:string)=>void;setSection:(s:Section)=>void;setModal:(m:string|null)=>void}){const{section}=p;useEffect(()=>{const fn=()=>p.setModal("profile");window.addEventListener("tf-profile",fn);return()=>window.removeEventListener("tf-profile",fn)},[p.setModal]);if(section==="dashboard")return <Dashboard {...p}/>;if(["reservations","confirm","preparation","active","completed","cancelled"].includes(section))return <Reservations {...p}/>;if(section==="planning")return <Planning {...p}/>;if(section==="motos")return <Motos {...p}/>;if(section==="circuits")return <Circuits {...p}/>;if(section==="services")return <Services {...p}/>;if(section==="maintenance")return <MaintenancePage {...p}/>;if(section==="map")return <MapPage {...p}/>;if(section==="clients")return <Clients {...p}/>;if(section==="complaints")return <Complaints {...p}/>;if(section==="team")return <Team {...p}/>;if(section==="users")return <UsersPage {...p}/>;if(section==="payments")return <Payments {...p}/>;if(section==="refunds")return <Refunds {...p}/>;if(section==="promotions")return <Promotions {...p}/>;if(section==="reports")return <Reports {...p}/>;return <ActivityPage {...p}/>}

function Dashboard({data,setSection,setModal}:{data:AppData;setSection:(s:Section)=>void;setModal:(m:string|null)=>void}){const revenue=data.payments.filter(p=>p.status==="Validé").reduce((s,p)=>s+p.amount,0);const kpis=[{label:"Chiffre d’affaires",value:money(revenue),delta:"+12,8%",icon:CircleDollarSign,tone:"terracotta"},{label:"Réservations aujourd’hui",value:"8",delta:"3 à confirmer",icon:CalendarDays,tone:"teal"},{label:"Excursions aujourd’hui",value:"6",delta:"3 en cours",icon:Navigation,tone:"petrol"},{label:"Clients",value:String(data.customers.length),delta:"+4 ce mois",icon:Users,tone:"sand"},{label:"Motos disponibles",value:String(data.motorcycles.filter(m=>m.status==="Disponible").length),delta:`sur ${data.motorcycles.length}`,icon:Bike,tone:"teal"},{label:"Motos en excursion",value:String(data.motorcycles.filter(m=>m.status==="En excursion").length),delta:"suivi GPS actif",icon:MapPin,tone:"petrol"},{label:"En maintenance",value:String(data.motorcycles.filter(m=>m.status==="Maintenance").length),delta:"1 planifiée",icon:Wrench,tone:"sand"},{label:"Paiements en attente",value:money(data.reservations.filter(r=>r.paid<r.total).reduce((s,r)=>s+r.total-r.paid,0)),delta:"7 dossiers",icon:CreditCard,tone:"terracotta"},{label:"Réclamations ouvertes",value:String(data.complaints.filter(c=>!["résolue","clôturée"].includes(c.status)).length),delta:"2 urgentes",icon:Headphones,tone:"sand"}];const timeline=[["08:30","Préparation moto","M-004 · Boucle Découverte"],["09:00","Départ excursion","RES-2026-00124 · Vallée et Villages"],["10:15","Arrivée étape","Belvédère de l’Atlas"],["11:30","Pause","Oasis de Tatiouine"],["13:00","Retour","M-008 · Base TiziFlow"],["14:00","Maintenance","M-011 · Contrôle batterie"],["15:00","Nouvelle réservation","RES-2026-00131 · 2 participants"],["17:30","Excursion sunset","Panorama des Crêtes"]];const alerts=[["danger","Réclamation urgente","CMP-2026-00017 · Retard retour","complaints"],["warning","Paiement en attente","RES-2026-00129 · 1 240 MAD","payments"],["warning","Maintenance due","M-004 · Révision sous 120 km","maintenance"],["danger","Excursion sans guide","RES-2026-00138 · Départ 14:30","planning"],["info","Batterie faible","M-011 · 35% · autonomie critique","motos"],["danger","Conflit planning","Guide Ahmed · 14:00–17:00","planning"]] as const;return <><PageTitle eyebrow="VENDREDI 02 OCTOBRE · 17:50" title="Centre des opérations" description="Vue temps réel de l’activité TiziFlow à Midelt." action="Nouvelle réservation" onAction={()=>setModal("newReservation")}/><div className="weather-strip"><div><Sun/><b>24°C</b><span>Midelt · ciel clair</span></div><div><Zap/><b>12 / 14</b><span>motos prêtes</span></div><div><ShieldCheck/><b>100%</b><span>équipes synchronisées</span></div><Button variant="ghost" onClick={()=>setSection("map")}>Ouvrir la carte live <ChevronRight/></Button></div><div className="kpi-grid">{kpis.map(k=><button key={k.label} className={`kpi-card ${k.tone}`} onClick={()=>setSection(k.label.includes("Paiement")?"payments":k.label.includes("Réclamation")?"complaints":k.label.includes("Moto")||k.label.includes("maintenance")?"motos":"reservations")}><span><k.icon/></span><div><small>{k.label}</small><strong>{k.value}</strong><em>{k.delta}</em></div></button>)}</div><div className="dashboard-grid"><section className="surface timeline-card"><header><div><span className="eyebrow">FLUX DU JOUR</span><h2>Chronologie opérationnelle</h2></div><Button variant="ghost" onClick={()=>setSection("planning")}>Voir planning <ChevronRight/></Button></header><div className="timeline">{timeline.map((t,i)=><button key={t[0]} onClick={()=>setSection(i===5?"maintenance":"reservations")}><time>{t[0]}</time><span className={i<4?"done":i===4?"now":""}/><div><b>{t[1]}</b><small>{t[2]}</small></div>{i===4&&<i>MAINTENANT</i>}<ChevronRight/></button>)}</div></section><section className="surface alerts-card"><header><div><span className="eyebrow">À TRAITER</span><h2>Centre d’alertes</h2></div><span className="alert-count">{alerts.length}</span></header><div className="alert-list">{alerts.map(a=><button key={a[1]} onClick={()=>setSection(a[3])}><span className={`alert-icon ${a[0]}`}><AlertTriangle/></span><div><b>{a[1]}</b><small>{a[2]}</small></div><ChevronRight/></button>)}</div></section></div><section className="quick-actions-band"><span className="eyebrow">ACTIONS RAPIDES</span><div>{[["Nouvelle réservation",CalendarDays,"newReservation"],["Nouveau client",UserRound,"newCustomer"],["Ajouter une moto",Bike,"newMoto"],["Créer un circuit",Navigation,"newCircuit"],["Ajouter un service",PackagePlus,"newService"],["Enregistrer paiement",CreditCard,"payment"],["Créer réclamation",Headphones,"complaint"],["Déclarer incident",AlertTriangle,"incident"]].map(([label,Icon,action])=><Button key={String(label)} variant="outline" onClick={()=>setModal(String(action))}>{typeof Icon!=="string"&&<Icon/>}{String(label)}</Button>)}</div></section></>}

function Toolbar({search,setSearch,filters=true}:{search:string;setSearch:(s:string)=>void;filters?:boolean}){return <div className="table-toolbar"><div className="table-search"><Search/><Input placeholder="Rechercher…" value={search} onChange={e=>setSearch(e.target.value)}/></div>{filters&&<><Button variant="outline"><Filter/>Filtres</Button><Button variant="outline"><ListFilter/>Trier</Button></>}<Button variant="outline" onClick={()=>{const blob=new Blob(["Export TiziFlow Mission Control"],{type:"text/csv"});const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download="tiziflow-export.csv";a.click();toast.success("Export généré")}}><ArrowDownToLine/>Exporter</Button></div>}
function Reservations({section,data,setData,selectedId,setSelectedId,setModal}:{section:Section;data:AppData;setData:Store["setData"];selectedId:string;setSelectedId:(id:string)=>void;setModal:(m:string|null)=>void}){const[search,setSearch]=useState("");const[page,setPage]=useState(1);const filterMap:Partial<Record<Section,string>>={confirm:"attente",preparation:"préparation",active:"cours",completed:"termin",cancelled:"annul"};const filtered=data.reservations.filter(r=>(!filterMap[section]||r.status.toLowerCase().includes(filterMap[section]??""))&&`${r.id} ${customerName(r.customerId,data)} ${circuitName(r.circuitId,data)} ${guideName(r.guideId,data)}`.toLowerCase().includes(search.toLowerCase()));const rows=filtered.slice((page-1)*10,page*10);const selected=data.reservations.find(r=>r.id===selectedId);return <><PageTitle eyebrow="RÉSERVATIONS" title={labels[section]} description={`${filtered.length} dossiers · disponibilité et paiements synchronisés`} action="Nouvelle réservation" onAction={()=>setModal("newReservation")} settings={()=>setModal("settings:reservations")}/><div className="surface data-surface"><Toolbar search={search} setSearch={setSearch}/><div className="table-scroll"><table><thead><tr>{["ID","Client","Circuit","Date / heure","Pers.","Moto","Guide","Montant","Paiement","Statut",""] .map(h=><th key={h}>{h}</th>)}</tr></thead><tbody>{rows.map(r=><tr key={r.id} className={r.id===selectedId?"selected":""} onClick={()=>setSelectedId(r.id)}><td><b>{r.id.replace("RES-2026-","")}</b></td><td>{customerName(r.customerId,data)}</td><td><span className="truncate-cell">{circuitName(r.circuitId,data)}</span><small>{r.activity}</small></td><td>{new Date(`${r.date}T12:00`).toLocaleDateString("fr-FR",{day:"2-digit",month:"short"})}<small>{r.time}</small></td><td>{r.participants}</td><td>{r.motorcycleIds.join(", ")}</td><td>{guideName(r.guideId,data).split(" ")[0]}</td><td><b>{money(r.total)}</b><small>Reste {money(r.total-r.paid)}</small></td><td><Badge>{r.paymentStatus}</Badge></td><td><Badge>{r.status}</Badge></td><td><IconButton label="Ouvrir"><ChevronRight/></IconButton></td></tr>)}</tbody></table></div><div className="pagination"><span>{(page-1)*10+1}–{Math.min(page*10,filtered.length)} sur {filtered.length}</span><div><IconButton label="Page précédente" onClick={()=>setPage(Math.max(1,page-1))}><ChevronLeft/></IconButton>{Array.from({length:Math.ceil(filtered.length/10)},(_,i)=><Button key={i} size="icon" variant={page===i+1?"default":"ghost"} onClick={()=>setPage(i+1)}>{i+1}</Button>)}<IconButton label="Page suivante" onClick={()=>setPage(Math.min(Math.ceil(filtered.length/10),page+1))}><ChevronRight/></IconButton></div></div></div>{selected&&<ReservationDrawer reservation={selected} data={data} setData={setData} close={()=>setSelectedId("")} goMap={()=>setSectionExternal("map")}/>}</>}
function setSectionExternal(section:Section){history.replaceState({},"",`?view=${section}`);window.location.reload()}
function ReservationDrawer({reservation:r,data,setData,close,goMap}:{reservation:Reservation;data:AppData;setData:Store["setData"];close:()=>void;goMap:()=>void}){const setStatus=(status:string)=>{setData(prev=>({...prev,reservations:prev.reservations.map(x=>x.id===r.id?{...x,status}:x),activity:[{id:`ACT-${Date.now()}`,user:"Admin TiziFlow",action:`a changé le statut en ${status}`,entity:r.id,date:new Date().toLocaleString("fr-FR"),previous:r.status,next:status},...prev.activity]}));toast.success(`${r.id} · ${status}`)};return <div className="drawer-layer"><button className="drawer-backdrop" onClick={close} aria-label="Fermer"/><aside className="entity-drawer"><header><div><span className="eyebrow">RÉSERVATION</span><h2>{r.id}</h2><Badge>{r.status}</Badge></div><IconButton label="Fermer" onClick={close}><X/></IconButton></header><div className="drawer-summary"><div><small>Total</small><b>{money(r.total)}</b></div><div><small>Payé</small><b>{money(r.paid)}</b></div><div><small>Restant</small><b className={r.total-r.paid>0?"danger-text":""}>{money(r.total-r.paid)}</b></div></div><div className="detail-block"><h3>Déroulé opérationnel</h3><div className="stepper">{["Demande reçue","Confirmée","Acompte payé","En préparation","En cours","Terminée"].map((x,i)=><div key={x} className={i<3?"done":""}><span>{i<3?<Check/>:i+1}</span><small>{x}</small></div>)}</div></div>{[["Client",customerName(r.customerId,data),"clients"],["Circuit",circuitName(r.circuitId,data),"circuits"],["Moto",r.motorcycleIds.join(", "),"motos"],["Guide",guideName(r.guideId,data),"team"],["Départ",`${r.date} · ${r.time}`,"planning"]].map(x=><button className="detail-link" key={x[0]} onClick={()=>setSectionExternal(x[2] as Section)}><span>{x[0]}</span><b>{x[1]}</b><ChevronRight/></button>)}<div className="detail-block"><h3>Actions</h3><div className="action-grid"><Button onClick={()=>setStatus("Confirmée")}><Check/>Confirmer</Button><Button variant="outline" onClick={()=>toast.success("Moto assignée")}>Assigner moto</Button><Button variant="outline" onClick={()=>toast.success("Guide assigné")}>Assigner guide</Button><Button variant="outline" onClick={()=>toast.success("Paiement enregistré")}>Enregistrer paiement</Button><Button variant="outline" onClick={()=>toast.success("Reçu REC-2026-00031 généré")}>Générer reçu</Button><Button variant="outline" onClick={goMap}><Map/>Voir carte</Button><Button variant="destructive" onClick={()=>setStatus("Annulée")}>Annuler</Button></div></div></aside></div>}

function Planning({data,setData,setModal}:{data:AppData;setData:Store["setData"];setModal:(m:string|null)=>void}){const[view,setView]=useState("Semaine");const[resource,setResource]=useState("circuit");const[selected,setSelected]=useState<Reservation|null>(null);const days=["Lun 28","Mar 29","Mer 30","Jeu 01","Ven 02","Sam 03","Dim 04"];const dayDates=["2026-09-28","2026-09-29","2026-09-30","2026-10-01","2026-10-02","2026-10-03","2026-10-04"];const reschedule=(r:Reservation,day:number,hour:string)=>{const candidate={...r,date:dayDates[day]??r.date,time:hour};const conflicts=validateReservation(candidate,data,r.id);if(conflicts.some(c=>c.blocking)){toast.error("Impossible de replanifier",{description:conflicts.map(c=>c.message).join(" · ")});return}setData(prev=>({...prev,reservations:prev.reservations.map(x=>x.id===r.id?candidate:x)}));toast.success("Réservation replanifiée")};return <><PageTitle eyebrow="PLANIFICATION RESSOURCES" title="Calendrier opérationnel" description="Circuits, guides et motos · détection automatique des conflits" action="Nouvelle réservation" onAction={()=>setModal("newReservation")} settings={()=>setModal("settings:reservations")}/><div className="calendar-controls"><div className="segmented">{["Jour","Semaine","Mois","Agenda"].map(x=><Button key={x} variant={view===x?"default":"ghost"} onClick={()=>setView(x)}>{x}</Button>)}</div><div className="segmented">{[["circuit","Circuits"],["guide","Guides"],["moto","Motos"]].map(x=><Button key={x[0]} variant={resource===x[0]?"secondary":"ghost"} onClick={()=>setResource(x[0]??"circuit")}>{x[1]}</Button>)}</div><Button variant="outline"><ChevronLeft/></Button><b>28 sept. — 4 oct. 2026</b><Button variant="outline"><ChevronRight/></Button></div><div className="surface resource-calendar"><div className="calendar-head"><span>GMT+1</span>{days.map((d,i)=><b key={d} className={i===4?"today":""}>{d}<small>{i===4?"Aujourd’hui":""}</small></b>)}</div>{["08:00","09:00","10:00","11:00","12:00","13:00","14:00","15:00","16:00","17:00"].map((hour,hi)=><div className="calendar-row" key={hour}><time>{hour}</time>{days.map((_,di)=>{const r=data.reservations[(hi*3+di)%data.reservations.length];const show=(hi+di)%3===0&&r;return <div key={di} className="calendar-cell" onDragOver={e=>e.preventDefault()} onDrop={e=>{const id=e.dataTransfer.getData("text/plain");const found=data.reservations.find(x=>x.id===id);if(found)reschedule(found,di,hour)}}>{show&&<button draggable onDragStart={e=>e.dataTransfer.setData("text/plain",r.id)} onClick={()=>setSelected(r)} className={`calendar-event ${statusTone(r.status)}`}><b>{r.time} · {resource==="circuit"?circuitName(r.circuitId,data):resource==="guide"?guideName(r.guideId,data):r.motorcycleIds[0]}</b><span>{r.id.replace("RES-2026-","")}</span><small>{r.participants} pers. · {r.status}</small></button>}</div>})}</div>)}</div><div className="calendar-legend"><span><i className="success"/>Disponible</span><span><i className="warning"/>À confirmer</span><span><i className="danger"/>Conflit</span><b>Glissez une réservation pour la replanifier</b></div>{selected&&<ReservationDrawer reservation={selected} data={data} setData={setData} close={()=>setSelected(null)} goMap={()=>setSectionExternal("map")}/>}</>}

function Motos({data,setData,setModal,selectedId,setSelectedId}:{data:AppData;setData:Store["setData"];setModal:(m:string|null)=>void;selectedId:string;setSelectedId:(s:string)=>void}){const[selected,setSelected]=useState(data.motorcycles.find(m=>m.id===selectedId));return <><PageTitle eyebrow="FLOTTE & EXCURSIONS" title="Motos" description={`${data.motorcycles.length} motos · ${data.motorcycles.filter(m=>m.status==="Disponible").length} disponibles`} action="Ajouter une moto" onAction={()=>setModal("newMoto")} settings={()=>setModal("settings:motos")}/><div className="fleet-summary"><div><Bike/><span><b>{data.motorcycles.length}</b>Total flotte</span></div><div><Zap/><span><b>{data.motorcycles.filter(m=>m.status==="Disponible").length}</b>Disponibles</span></div><div><Navigation/><span><b>3</b>En excursion</span></div><div><Wrench/><span><b>2</b>À l’atelier</span></div></div><div className="fleet-grid">{data.motorcycles.map((m,i)=><button key={m.id} className="moto-card" onClick={()=>{setSelected(m);setSelectedId(m.id)}}><div className="moto-image" style={{backgroundImage:`url(${motoImage})`}}><Badge>{m.status}</Badge><span>{m.id}</span></div><div className="moto-info"><div><h3>{m.model}</h3><small>{m.brand} · {m.category}</small></div><div className="battery-row"><BatteryCharging/><b>{m.battery}%</b><Progress value={m.battery}/></div><div className="moto-stats"><span><b>{m.autonomy} km</b>Autonomie</span><span><b>{m.mileage.toLocaleString("fr-FR")} km</b>Kilométrage</span></div><footer><span><MapPin/> {i%2?"Piste Tatiouine":"Base Midelt"}</span><ChevronRight/></footer></div></button>)}</div>{selected&&<Modal title={`${selected.id} · ${selected.model}`} wide onClose={()=>setSelected(undefined)}><div className="vehicle-detail"><div className="vehicle-photo" style={{backgroundImage:`url(${motoImage})`}}><Badge>{selected.status}</Badge></div><div><div className="drawer-summary"><div><small>Batterie</small><b>{selected.battery}%</b></div><div><small>Autonomie</small><b>{selected.autonomy} km</b></div><div><small>Kilométrage</small><b>{selected.mileage.toLocaleString("fr-FR")} km</b></div></div><div className="detail-block"><h3>État opérationnel</h3><p>Dernière maintenance <b>{selected.lastMaintenance}</b></p><p>Prochaine maintenance <b>{selected.nextMaintenance}</b></p><p>GPS <b>{selected.position.join(", ")}</b></p></div><div className="action-grid"><Button onClick={()=>toast.success("Moto assignée")}>Assigner</Button><Button variant="outline" onClick={()=>setSectionExternal("map")}><Map/>Suivi GPS</Button><Button variant="outline" onClick={()=>toast.success("Maintenance programmée")}>Programmer maintenance</Button><Button variant="outline" onClick={()=>toast.success("Incident créé")}>Déclarer incident</Button><Button variant="destructive" onClick={()=>{setData(prev=>({...prev,motorcycles:prev.motorcycles.map(m=>m.id===selected.id?{...m,status:"Archivée"}:m)}));toast.success("Moto archivée");setSelected(undefined)}}><Archive/>Archiver</Button></div></div></div></Modal>}</>}

function Circuits({data,setData,setModal}:{data:AppData;setData:Store["setData"];setModal:(m:string|null)=>void}){const[selected,setSelected]=useState(data.circuits[0]);const[tab,setTab]=useState("Vue d’ensemble");if(selected&&tab!=="Liste")return <><div className="detail-hero" style={{backgroundImage:`url(${selected.image})`}}><Button variant="secondary" onClick={()=>{setSelected(undefined);setTab("Liste")}}><ChevronLeft/>Tous les circuits</Button><div><span className="eyebrow light">CIRCUIT DE DÉMONSTRATION</span><h1>{selected.name}</h1><p>{selected.description}</p><div className="hero-meta"><span>{selected.duration}</span><span>{selected.distance} km</span><span>{selected.difficulty}</span><span>{money(selected.price)}</span></div></div></div><div className="detail-tabs">{["Vue d’ensemble","Itinéraire","Carte","Réservations","Calendrier","Services"].map(x=><Button variant={tab===x?"default":"ghost"} onClick={()=>setTab(x)} key={x}>{x}</Button>)}<Button variant="outline" onClick={()=>setModal("settings:circuits")}><Settings2/>Paramètres</Button></div>{tab==="Itinéraire"?<CircuitBuilder circuit={selected} data={data} setData={setData} setSelected={setSelected}/>:tab==="Calendrier"?<CircuitCalendar circuit={selected} data={data}/>:tab==="Carte"?<div className="surface map-mini"><Suspense fallback={<div className="skeleton-map"/>}><LiveMap data={data}/></Suspense></div>:<CircuitOverview circuit={selected} data={data} tab={tab}/>}</>;return <><PageTitle eyebrow="FLOTTE & EXCURSIONS" title="Circuits" description="Parcours de démonstration inspirés de Midelt et de l’Atlas" action="Créer un circuit" onAction={()=>setModal("newCircuit")} settings={()=>setModal("settings:circuits")}/><div className="circuit-grid">{data.circuits.map(c=><button className="circuit-card" key={c.id} onClick={()=>{setSelected(c);setTab("Vue d’ensemble")}}><img src={c.image} alt=""/><div className="circuit-overlay"/><div className="circuit-content"><Badge>{c.difficulty}</Badge><h2>{c.name}</h2><p>{c.duration} · {c.distance} km · capacité {c.capacity}</p><footer><b>{money(c.price)}</b><span>Ouvrir <ChevronRight/></span></footer></div></button>)}</div></>}
function CircuitOverview({circuit:c,data,tab}:{circuit:AppData["circuits"][number];data:AppData;tab:string}){if(tab==="Réservations")return <div className="surface data-surface"><table><thead><tr><th>Réservation</th><th>Client</th><th>Date</th><th>Participants</th><th>Paiement</th></tr></thead><tbody>{data.reservations.filter(r=>r.circuitId===c.id).map(r=><tr key={r.id}><td>{r.id}</td><td>{customerName(r.customerId,data)}</td><td>{r.date} · {r.time}</td><td>{r.participants}</td><td><Badge>{r.paymentStatus}</Badge></td></tr>)}</tbody></table></div>;return <div className="overview-grid"><section className="surface"><span className="eyebrow">DESCRIPTION</span><h2>Une lecture opérationnelle du parcours</h2><p>{c.description}</p><div className="spec-grid"><span><small>Départ</small><b>Base TiziFlow, Midelt</b></span><span><small>Retour</small><b>Selon créneau · +{c.duration}</b></span><span><small>Âge minimum</small><b>18 ans</b></span><span><small>Capacité</small><b>{c.capacity} participants</b></span></div></section><section className="surface"><span className="eyebrow">PROCHAINS DÉPARTS</span><h2>Capacité disponible</h2>{data.reservations.filter(r=>r.circuitId===c.id).slice(0,4).map(r=><div className="capacity-row" key={r.id}><div><b>{r.time} · {r.id}</b><small>{r.participants} participants · {guideName(r.guideId,data)}</small></div><div><b>{r.participants} / {c.capacity}</b><Progress value={r.participants/c.capacity*100}/><small>{c.capacity-r.participants} places restantes</small></div></div>)}</section></div>}
function CircuitBuilder({circuit,data,setData,setSelected}:{circuit:AppData["circuits"][number];data:AppData;setData:Store["setData"];setSelected:(c:AppData["circuits"][number])=>void}){const updateStops=(stops:typeof circuit.stops)=>{const next={...circuit,stops,distance:Math.max(12,Math.round(stops.length*16.4)),duration:`${Math.max(2,Math.round(stops.reduce((s,x)=>s+x.duration,0)/30))} h`};setSelected(next);setData(prev=>({...prev,circuits:prev.circuits.map(c=>c.id===next.id?next:c)}))};return <div className="builder-layout"><section className="surface"><div className="builder-header"><div><span className="eyebrow">CIRCUIT BUILDER</span><h2>{circuit.stops.length} étapes · {circuit.distance} km · {circuit.duration}</h2></div><Button onClick={()=>{updateStops([...circuit.stops,{id:`ST-${Date.now()}`,name:"Nouvelle étape",type:"Point d’intérêt",lat:32.7,lng:-4.72,duration:20,description:"À compléter"}]);toast.success("Étape ajoutée")}}><Plus/>Ajouter une étape</Button></div><div className="stop-list">{circuit.stops.map((s,i)=><div className="stop-row" key={s.id}><GripVertical/><span>{i+1}</span><div><b>{s.name}</b><small>{s.type} · {s.duration} min · {s.lat.toFixed(4)}, {s.lng.toFixed(4)}</small></div><IconButton label="Dupliquer" onClick={()=>updateStops([...circuit.stops.slice(0,i+1),{...s,id:`${s.id}-copy`,name:`${s.name} · copie`},...circuit.stops.slice(i+1)])}><PackagePlus/></IconButton><IconButton label="Modifier" onClick={()=>toast.success("Étape prête à être modifiée")}><Pencil/></IconButton><IconButton label="Supprimer" onClick={()=>{updateStops(circuit.stops.filter(x=>x.id!==s.id));toast.success("Étape supprimée")}}><Trash2/></IconButton></div>)}</div></section><section className="surface route-preview"><span className="eyebrow">APERÇU ITINÉRAIRE</span><div className="mini-route">{circuit.stops.map((s,i)=><div key={s.id}><span>{i+1}</span><b>{s.name}</b></div>)}</div><p>Le tracé, la distance, la durée et la chronologie sont recalculés après chaque modification.</p></section></div>}
function CircuitCalendar({circuit:c,data}:{circuit:AppData["circuits"][number];data:AppData}){return <section className="surface circuit-calendar"><header><h2>Calendrier · {c.name}</h2><Badge>{c.capacity} places maximum</Badge></header>{data.reservations.filter(r=>r.circuitId===c.id).slice(0,8).map(r=><div className="circuit-slot" key={r.id}><time>{new Date(`${r.date}T12:00`).toLocaleDateString("fr-FR",{weekday:"short",day:"2-digit",month:"short"})}<b>{r.time}</b></time><div><b>{r.id}</b><small>{r.participants} participants · {r.motorcycleIds.length} moto(s)</small></div><div><span>Guide</span><b>{guideName(r.guideId,data)}</b></div><div><b>{r.participants} / {c.capacity}</b><Progress value={r.participants/c.capacity*100}/><small>{c.capacity-r.participants} places restantes</small></div><Badge>{r.paymentStatus}</Badge></div>)}</section>}

function Services({data,setModal}:{data:AppData;setModal:(m:string|null)=>void}){return <><PageTitle eyebrow="FLOTTE & EXCURSIONS" title="Services" description={`${data.services.length} prestations complémentaires`} action="Ajouter un service" onAction={()=>setModal("newService")} settings={()=>setModal("settings:services")}/><div className="service-grid">{data.services.map((s,i)=><article className="surface service-card" key={s.id}><span className={`service-icon s${i%4}`}>{[Headphones,Navigation,Sparkles,BatteryCharging][i%4]&&(()=>{const I=[Headphones,Navigation,Sparkles,BatteryCharging][i%4]??Sparkles;return <I/>})()}</span><div><Badge>{s.status}</Badge><h2>{s.name}</h2><p>{["Accompagnement expert des pistes de l’Atlas.","Prise en charge coordonnée avec le départ.","Expérience adaptée au rythme du groupe."][i%3]}</p></div><div className="service-meta"><span><small>Prix</small><b>{money(s.price)}</b></span><span><small>Durée</small><b>{s.duration}</b></span><span><small>Capacité</small><b>{s.capacity}</b></span></div><footer><Badge>{s.type}</Badge><Button variant="ghost" onClick={()=>toast.success(`${s.name} modifié`)}><Pencil/>Modifier</Button></footer></article>)}</div></>}
function MaintenancePage({data,setData,setModal}:{data:AppData;setData:Store["setData"];setModal:(m:string|null)=>void}){return <><PageTitle eyebrow="ATELIER & DISPONIBILITÉ" title="Maintenance" description="Toute intervention planifiée bloque automatiquement la moto concernée." action="Programmer maintenance" onAction={()=>setModal("incident")} settings={()=>setModal("settings:maintenance")}/><div className="surface data-surface"><Toolbar search="" setSearch={()=>{}}/><table><thead><tr><th>ID</th><th>Moto</th><th>Intervention</th><th>Date</th><th>Kilométrage</th><th>Technicien</th><th>Coût</th><th>Prochaine</th><th>Statut</th><th/></tr></thead><tbody>{data.maintenance.map(m=><tr key={m.id}><td><b>{m.id}</b></td><td>{m.motorcycleId}</td><td>{m.type}<small>{m.description}</small></td><td>{m.date}</td><td>{m.mileage.toLocaleString("fr-FR")} km</td><td>{m.technician}</td><td>{money(m.cost)}</td><td>{m.nextDate}</td><td><Badge>{m.status}</Badge></td><td><IconButton label="Terminer" onClick={()=>{setData(prev=>({...prev,maintenance:prev.maintenance.map(x=>x.id===m.id?{...x,status:"Terminée"}:x)}));toast.success("Maintenance terminée")}}><Check/></IconButton></td></tr>)}</tbody></table></div></>}
function MapPage({data,setModal}:{data:AppData;setModal:(m:string|null)=>void}){return <><PageTitle eyebrow="SUIVI TEMPS RÉEL" title="Carte opérationnelle" description="Motos, circuits, progression et alertes autour de Midelt." action="Déclarer incident" onAction={()=>setModal("incident")} settings={()=>setModal("settings:circuits")}/><div className="live-map-shell"><Suspense fallback={<div className="skeleton-map"><RefreshCcw className="animate-spin"/>Chargement de la carte…</div>}><LiveMap data={data}/></Suspense></div></>}

function Clients({data,setModal,selectedId,setSelectedId}:{data:AppData;setModal:(m:string|null)=>void;selectedId:string;setSelectedId:(s:string)=>void}){const[q,setQ]=useState("");const[selected,setSelected]=useState(data.customers.find(c=>c.id===selectedId));const filtered=data.customers.filter(c=>`${c.firstName} ${c.lastName} ${c.email} ${c.country}`.toLowerCase().includes(q.toLowerCase()));return <><PageTitle eyebrow="CLIENTS & ÉQUIPE" title="Clients" description={`${data.customers.length} profils · historique unifié`} action="Nouveau client" onAction={()=>setModal("newCustomer")} settings={()=>setModal("settings:clients")}/><div className="surface data-surface"><Toolbar search={q} setSearch={setQ}/><table><thead><tr><th>Client</th><th>Pays</th><th>Contact</th><th>Langue</th><th>Réservations</th><th>Total dépensé</th><th>Dernière réservation</th><th>Statut</th><th/></tr></thead><tbody>{filtered.map(c=><tr key={c.id} onClick={()=>{setSelected(c);setSelectedId(c.id)}}><td><div className="person-cell"><span>{c.firstName[0]}{c.lastName[0]}</span><b>{c.firstName} {c.lastName}</b></div></td><td>{c.country}</td><td>{c.email}<small>{c.phone}</small></td><td>{c.language.toUpperCase()}</td><td>{c.reservations}</td><td><b>{money(c.spent)}</b></td><td>{c.lastReservation}</td><td><Badge>{c.status}</Badge></td><td><ChevronRight/></td></tr>)}</tbody></table></div>{selected&&<Modal title={`${selected.firstName} ${selected.lastName}`} wide onClose={()=>setSelected(undefined)}><div className="profile-heading"><div className="large-avatar">{selected.firstName[0]}{selected.lastName[0]}</div><div><Badge>{selected.status}</Badge><p>{selected.email} · {selected.phone}</p><p>{selected.country} · langue {selected.language.toUpperCase()}</p></div></div><div className="detail-tabs">{["Informations","Réservations","Paiements","Excursions","Réclamations","Notes"].map(x=><Button variant={x==="Informations"?"default":"ghost"} key={x}>{x}</Button>)}</div><div className="drawer-summary"><div><small>Réservations</small><b>{selected.reservations}</b></div><div><small>Total dépensé</small><b>{money(selected.spent)}</b></div><div><small>Dernière visite</small><b>{selected.lastReservation}</b></div></div><div className="detail-block"><h3>Notes internes</h3><Textarea defaultValue={selected.notes||"Client ponctuel. Aucun besoin particulier signalé."}/></div><div className="modal-actions"><Button variant="outline" onClick={()=>setModal("complaint")}>Créer réclamation</Button><Button onClick={()=>toast.success("Profil client enregistré")}>Enregistrer</Button></div></Modal>}</>}
function Complaints({data,setData,setModal}:{data:AppData;setData:Store["setData"];setModal:(m:string|null)=>void}){return <><PageTitle eyebrow="QUALITÉ DE SERVICE" title="Réclamations" description={`${data.complaints.filter(c=>!["résolue","clôturée"].includes(c.status)).length} dossiers ouverts`} action="Créer une réclamation" onAction={()=>setModal("complaint")}/><div className="complaint-board">{["nouvelle","en cours","attente client","résolue"].map(status=><section key={status}><header><h2>{status}</h2><span>{data.complaints.filter(c=>c.status===status).length}</span></header>{data.complaints.filter(c=>c.status===status).map(c=><article className="surface" key={c.id}><div><Badge>{c.priority}</Badge><small>{c.id}</small></div><h3>{c.description}</h3><p>{customerName(c.customerId,data)} · {c.category}</p><footer><span>{c.agent.split(" ")[0]}</span><Button size="sm" variant="outline" onClick={()=>{setData(prev=>({...prev,complaints:prev.complaints.map(x=>x.id===c.id?{...x,status:"résolue",resolution:"Résolution validée par l’équipe"}:x)}));toast.success("Réclamation résolue")}}>Résoudre</Button></footer></article>)}</section>)}</div></>}
function Team({data,setModal}:{data:AppData;setModal:(m:string|null)=>void}){const[calendar,setCalendar]=useState(false);return <><PageTitle eyebrow="CLIENTS & ÉQUIPE" title="Équipe & guides" description="Disponibilités et charge terrain sans chevauchement." action={calendar?"Voir les guides":"Calendrier guides"} onAction={()=>setCalendar(!calendar)} settings={()=>setModal("settings:team")}/>{calendar?<Planning data={data} setData={()=>{}} setModal={setModal}/>:<div className="team-grid">{data.guides.map((g,i)=><article className="surface team-card" key={g.id}><div className="guide-avatar">{g.name.split(" ").map(n=>n[0]).slice(0,2).join("")}</div><div><Badge>{g.status}</Badge><h2>{g.name}</h2><p>{g.role}</p></div><div className="guide-data"><span>{g.languages.join(" · ")}</span><span>{g.excursions} excursions</span><span>{g.phone}</span></div><Button variant="outline" onClick={()=>setCalendar(true)}><CalendarDays/>Voir le planning</Button></article>)}</div>}</>}
function UsersPage({setModal}:{setModal:(m:string|null)=>void}){const users=[{name:"Admin TiziFlow",role:"Admin",scope:"Accès complet",status:"Actif"},{name:"Nadia El Idrissi",role:"Responsable",scope:"Opérations, clients, flotte",status:"Actif"},{name:"Youssef Aït Ali",role:"Guide",scope:"Excursions assignées, carte",status:"Actif"},{name:"Karim Boulahya",role:"Fleet Manager",scope:"Motos, maintenance, affectations",status:"Actif"}];return <><PageTitle eyebrow="ACCÈS INTERNES" title="Utilisateurs" description="Rôles et droits des membres de l’équipe." action="Inviter un utilisateur" onAction={()=>toast.success("Invitation prête à être envoyée")} settings={()=>setModal("settings:users")}/><div className="permission-matrix surface"><table><thead><tr><th>Utilisateur</th><th>Rôle</th><th>Périmètre</th><th>Voir</th><th>Créer</th><th>Modifier</th><th>Supprimer</th><th>Exporter</th><th>Statut</th></tr></thead><tbody>{users.map((u,i)=><tr key={u.name}><td><div className="person-cell"><span>{u.name.split(" ").map(n=>n[0]).slice(0,2).join("")}</span><b>{u.name}</b></div></td><td><Badge>{u.role}</Badge></td><td>{u.scope}</td>{[0,1,2,3,4].map(x=><td key={x}>{i===2&&x>1?<X className="permission-no"/>:<Check className="permission-yes"/>}</td>)}<td><Badge>{u.status}</Badge></td></tr>)}</tbody></table></div></>}

function Payments({data,setModal}:{data:AppData;setModal:(m:string|null)=>void}){const[channel,setChannel]=useState("Tous");const visible=data.payments.filter(p=>channel==="Tous"||p.channel===channel);const total=visible.filter(p=>p.status==="Validé").reduce((s,p)=>s+p.amount,0);return <><PageTitle eyebrow="FINANCE & RAPPORTS" title="Paiements" description="Trois canaux, une vue consolidée des encaissements." action="Enregistrer paiement" onAction={()=>setModal("payment")} settings={()=>setModal("settings:payments")}/><div className="finance-summary"><div><small>Total encaissé</small><b>{money(data.payments.filter(p=>p.status==="Validé").reduce((s,p)=>s+p.amount,0))}</b><span>+8,4% ce mois</span></div>{["En ligne","Carte à l’agence","Espèces à l’agence"].map((x,i)=><button key={x} onClick={()=>setChannel(x)}><span className={`pay-icon p${i}`}><CreditCard/></span><small>{x}</small><b>{money(data.payments.filter(p=>p.channel===x&&p.status==="Validé").reduce((s,p)=>s+p.amount,0))}</b></button>)}</div><div className="surface data-surface"><div className="table-toolbar"><div className="segmented">{["Tous","En ligne","Carte à l’agence","Espèces à l’agence"].map(x=><Button key={x} variant={channel===x?"default":"ghost"} onClick={()=>setChannel(x)}>{x}</Button>)}</div><b>{money(total)} affichés</b></div><table><thead><tr><th>Transaction</th><th>Réservation</th><th>Client</th><th>Canal</th><th>Montant</th><th>Date</th><th>Référence</th><th>Agent</th><th>Statut</th></tr></thead><tbody>{visible.map(p=><tr key={p.id}><td><b>{p.id}</b></td><td>{p.reservationId}</td><td>{customerName(p.customerId,data)}</td><td>{p.channel}</td><td><b>{money(p.amount)}</b></td><td>{p.date}</td><td>{p.reference}</td><td>{p.agent}</td><td><Badge>{p.status}</Badge></td></tr>)}</tbody></table></div></>}
function Refunds({data,setData}:{data:AppData;setData:Store["setData"]}){const[amount,setAmount]=useState("");const[reservationId,setReservationId]=useState(data.reservations[0]?.id??"");const r=data.reservations.find(x=>x.id===reservationId);const refundable=r?.paid??0;const submit=()=>{const n=Number(amount);if(!r||n<=0||n>refundable){toast.error("Montant invalide",{description:`Le remboursement ne peut pas dépasser ${money(refundable)}.`});return}setData(prev=>({...prev,activity:[{id:`ACT-${Date.now()}`,user:"Admin TiziFlow",action:`a créé un remboursement de ${money(n)}`,entity:r.id,date:new Date().toLocaleString("fr-FR"),previous:"—",next:"En attente"},...prev.activity]}));toast.success("Remboursement créé");setAmount("")};return <><PageTitle eyebrow="FINANCE & RAPPORTS" title="Remboursements" description="Contrôle automatique du montant remboursable."/><div className="refund-layout"><section className="surface refund-form"><span className="eyebrow">NOUVELLE DEMANDE</span><h2>Créer un remboursement</h2><Label>Réservation</Label><Select value={reservationId} onValueChange={setReservationId}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent>{data.reservations.slice(0,12).map(x=><SelectItem value={x.id} key={x.id}>{x.id} · {customerName(x.customerId,data)}</SelectItem>)}</SelectContent></Select><div className="drawer-summary"><div><small>Total</small><b>{money(r?.total??0)}</b></div><div><small>Payé</small><b>{money(r?.paid??0)}</b></div><div><small>Remboursable</small><b>{money(refundable)}</b></div></div><Label>Montant à rembourser</Label><Input type="number" min={1} max={refundable} value={amount} onChange={e=>setAmount(e.target.value)} placeholder="0 MAD"/><Label>Motif</Label><Textarea placeholder="Motif opérationnel obligatoire" maxLength={500}/><Button onClick={submit}>Créer le remboursement</Button></section><section className="surface refund-history"><h2>Demandes récentes</h2>{data.activity.filter(a=>a.action.includes("remboursement")).map(a=><div key={a.id}><CreditCard/><div><b>{a.action}</b><small>{a.entity} · {a.user}</small></div><Badge>{a.next}</Badge></div>)}</section></div></>}
function Promotions({data,setData}:{data:AppData;setData:Store["setData"]}){return <><PageTitle eyebrow="FINANCE & RAPPORTS" title="Promotions" description="Codes, règles d’éligibilité et limites d’utilisation." action="Créer une promotion" onAction={()=>toast.success("Nouvelle promotion créée")}/><div className="promo-grid">{data.promotions.map(p=><article className="surface promo-card" key={p.id}><div><span className="promo-code">{p.code}</span><Badge>{p.status}</Badge></div><strong>{p.type==="Pourcentage"?`${p.value}%`:`${p.value} MAD`}</strong><p>Réservation minimum · {money(p.minimum)}</p><div><span>Utilisations</span><b>{p.used} / {p.limit}</b><Progress value={p.used/p.limit*100}/></div><footer><small>{p.start} → {p.end}</small><Switch checked={p.status==="Active"} onCheckedChange={v=>{setData(prev=>({...prev,promotions:prev.promotions.map(x=>x.id===p.id?{...x,status:v?"Active":"Inactive"}:x)}));toast.success("Promotion mise à jour")}}/></footer></article>)}</div></>}
function Reports({data}:{data:AppData}){const[period,setPeriod]=useState("Mois");const values=[46,62,55,78,68,91,82,74,94,86,100,88];const max=Math.max(...values);return <><PageTitle eyebrow="ANALYSE OPÉRATIONNELLE" title="Rapports" description="Revenus, activité et utilisation de la flotte."/><div className="report-filter"><div className="segmented">{["Jour","Semaine","Mois","Année"].map(x=><Button key={x} variant={period===x?"default":"ghost"} onClick={()=>setPeriod(x)}>{x}</Button>)}</div><Input type="date" defaultValue="2026-10-01"/><span>au</span><Input type="date" defaultValue="2026-10-31"/><Button variant="outline"><ArrowDownToLine/>Exporter PDF</Button></div><div className="report-kpis"><article><small>Revenu {period.toLowerCase()}</small><b>{money(86420)}</b><span>+14,2%</span></article><article><small>Réservations confirmées</small><b>42</b><span>87,5%</span></article><article><small>Participants</small><b>106</b><span>2,5 / sortie</span></article><article><small>Utilisation flotte</small><b>73%</b><span>+5,1%</span></article></div><div className="reports-grid"><section className="surface chart-card"><header><div><span className="eyebrow">CHIFFRE D’AFFAIRES</span><h2>Revenus par circuit</h2></div><b>{money(86420)}</b></header><div className="bar-chart">{values.map((v,i)=><div key={i}><span style={{height:`${v/max*100}%`}}/><small>{i+1}</small></div>)}</div></section><section className="surface"><span className="eyebrow">PERFORMANCE</span><h2>Circuits les plus demandés</h2>{data.circuits.slice(0,5).map((c,i)=><div className="ranking" key={c.id}><span>{i+1}</span><div><b>{c.name}</b><Progress value={92-i*13}/></div><strong>{money(18400-i*1870)}</strong></div>)}</section></div></>}
function ActivityPage({data}:{data:AppData}){return <><PageTitle eyebrow="TRAÇABILITÉ" title="Journal d’activité" description="Historique des changements, affectations et opérations sensibles."/><div className="surface activity-list">{data.activity.map(a=><div key={a.id}><span className="activity-icon"><Activity/></span><div><p><b>{a.user}</b> {a.action} <strong>{a.entity}</strong></p><small>{a.date}</small></div><div className="change"><span>{a.previous}</span><ChevronRight/><b>{a.next}</b></div></div>)}</div></>}

function QuickActions({onClose,action}:{onClose:()=>void;action:(s:string)=>void}){const items=[["Nouvelle réservation",CalendarDays,"newReservation"],["Nouveau client",UserRound,"newCustomer"],["Ajouter une moto",Bike,"newMoto"],["Créer un circuit",Navigation,"newCircuit"],["Enregistrer paiement",CreditCard,"payment"],["Créer réclamation",Headphones,"complaint"],["Déclarer incident",AlertTriangle,"incident"]];return <Modal title="Action rapide" onClose={onClose}><div className="quick-modal-grid">{items.map(([x,I,a])=><Button variant="outline" key={String(x)} onClick={()=>action(String(a))}>{typeof I!=="string"&&<I/>}{String(x)}<ChevronRight/></Button>)}</div></Modal>}
function Notifications({onClose,data,go}:{onClose:()=>void;data:AppData;go:(s:Section)=>void}){const items=[["Réservation à confirmer",data.reservations[4]?.id,"confirm"],["Paiement reçu",data.payments[1]?.id,"payments"],["Batterie faible","M-011 · 35%","motos"],["Réclamation urgente",data.complaints[2]?.id,"complaints"],["Maintenance à prévoir","M-004 · sous 120 km","maintenance"]] as const;return <Modal title="Centre de notifications" onClose={onClose}><div className="notification-list">{items.map((x,i)=><button key={x[0]} onClick={()=>{go(x[2]);onClose()}}><span className={i===2||i===3?"danger":""}><Bell/></span><div><b>{x[0]}</b><small>{x[1]}</small></div><ChevronRight/></button>)}</div><h3 className="mt-6">Préférences</h3>{["Interne","E-mail","WhatsApp","SMS"].map((x,i)=><div className="notification-pref" key={x}><span>{x}</span><Switch defaultChecked={i<3}/></div>)}</Modal>}
function SimpleCreate({title,fields,onClose}:{title:string;fields:string[];onClose:()=>void}){const[busy,setBusy]=useState(false);return <Modal title={title} onClose={onClose}><form onSubmit={e=>{e.preventDefault();setBusy(true);window.setTimeout(()=>{toast.success(`${title} enregistré`);onClose()},550)}}><div className="form-grid">{fields.map((f,i)=><label key={f} className={i===fields.length-1&&fields.length>5?"full":""}>{f}{f.includes("Description")?<Textarea required maxLength={500}/>:<Input required maxLength={120}/>}</label>)}</div><div className="modal-actions"><Button variant="outline" type="button" onClick={onClose}>Annuler</Button><Button disabled={busy}>{busy?<RefreshCcw className="animate-spin"/>:<Check/>}{busy?"Enregistrement…":"Enregistrer"}</Button></div></form></Modal>}
function ReservationWizard({data,setData,onClose}:{data:AppData;setData:Store["setData"];onClose:()=>void}){const[step,setStep]=useState(1);const[form,setForm]=useState({customerId:data.customers[0]?.id??"",circuitId:data.circuits[0]?.id??"",date:"2026-10-12",time:"09:00",participants:2,guideId:data.guides[1]?.id??"",motorcycleId:data.motorcycles[0]?.id??"",paid:0});const circuit=data.circuits.find(c=>c.id===form.circuitId)??data.circuits[0];const candidate:Reservation={id:`RES-2026-${String(124+data.reservations.length).padStart(5,"0")}`,customerId:form.customerId,circuitId:form.circuitId,activity:"Circuit guidé",date:form.date,time:form.time,participants:form.participants,motorcycleIds:[form.motorcycleId],guideId:form.guideId,total:(circuit?.price??0)*form.participants,paid:form.paid,paymentStatus:form.paid===0?"Non payé":"Acompte payé",status:"En attente confirmation"};const conflicts=validateReservation(candidate,data);const save=()=>{if(conflicts.some(c=>c.blocking)){toast.error("Disponibilité non validée",{description:conflicts.map(c=>c.message).join(" · ")});return}setData(prev=>({...prev,reservations:[candidate,...prev.reservations]}));toast.success(`${candidate.id} créée`);onClose()};return <Modal title="Nouvelle réservation" wide onClose={onClose}><div className="wizard-steps">{["Client","Activité","Créneau","Disponibilité","Affectation","Paiement","Confirmation"].map((x,i)=><div className={i+1===step?"active":i+1<step?"done":""} key={x}><span>{i+1<step?<Check/>:i+1}</span><small>{x}</small></div>)}</div><div className="wizard-content">{step===1&&<div><h3>Choisir le client</h3><Select value={form.customerId} onValueChange={v=>setForm({...form,customerId:v})}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent>{data.customers.map(c=><SelectItem key={c.id} value={c.id}>{c.firstName} {c.lastName} · {c.country}</SelectItem>)}</SelectContent></Select></div>}{step===2&&<div><h3>Sélectionner l’activité</h3><Select value={form.circuitId} onValueChange={v=>setForm({...form,circuitId:v})}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent>{data.circuits.map(c=><SelectItem key={c.id} value={c.id}>{c.name} · {money(c.price)}</SelectItem>)}</SelectContent></Select></div>}{step===3&&<div className="form-grid"><label>Date<Input type="date" value={form.date} onChange={e=>setForm({...form,date:e.target.value})}/></label><label>Heure<Input type="time" value={form.time} onChange={e=>setForm({...form,time:e.target.value})}/></label><label>Participants<Input type="number" min={1} max={8} value={form.participants} onChange={e=>setForm({...form,participants:Number(e.target.value)})}/></label></div>}{step===4&&<div><h3>Contrôle de disponibilité</h3>{conflicts.length?conflicts.map(c=><div className={`validation-row ${c.blocking?"danger":"warning"}`} key={c.message}><AlertTriangle/><div><b>{c.blocking?"Indisponible":"Attention"}</b><p>{c.message}</p></div></div>):<div className="validation-success"><ShieldCheck/><div><b>Toutes les ressources sont disponibles</b><p>Capacité, guides, motos et maintenance vérifiés.</p></div></div>}</div>}{step===5&&<div className="form-grid"><label>Moto<Select value={form.motorcycleId} onValueChange={v=>setForm({...form,motorcycleId:v})}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent>{data.motorcycles.map(m=><SelectItem disabled={["Maintenance","Hors service","Archivée"].includes(m.status)} key={m.id} value={m.id}>{m.id} · {m.model} · {m.status}</SelectItem>)}</SelectContent></Select></label><label>Guide<Select value={form.guideId} onValueChange={v=>setForm({...form,guideId:v})}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent>{data.guides.map(g=><SelectItem disabled={g.status==="Hors service"} key={g.id} value={g.id}>{g.name} · {g.status}</SelectItem>)}</SelectContent></Select></label></div>}{step===6&&<div><h3>Paiement</h3><div className="drawer-summary"><div><small>Total</small><b>{money(candidate.total)}</b></div><div><small>Acompte conseillé</small><b>{money(candidate.total*.3)}</b></div><div><small>Restant</small><b>{money(candidate.total-form.paid)}</b></div></div><Label>Montant encaissé maintenant</Label><Input type="number" min={0} max={candidate.total} value={form.paid} onChange={e=>setForm({...form,paid:Number(e.target.value)})}/></div>}{step===7&&<div className="confirmation-card"><ShieldCheck/><h3>Prête à confirmer</h3><p>{customerName(candidate.customerId,data)} · {circuitName(candidate.circuitId,data)}</p><b>{candidate.date} à {candidate.time} · {candidate.participants} participants</b><strong>{money(candidate.total)}</strong></div>}</div><div className="modal-actions"><Button variant="outline" disabled={step===1} onClick={()=>setStep(s=>s-1)}>Précédent</Button>{step<7?<Button onClick={()=>setStep(s=>s+1)}>Continuer<ChevronRight/></Button>:<Button onClick={save} disabled={conflicts.some(c=>c.blocking)}><Check/>Créer la réservation</Button>}</div></Modal>}
function PaymentModal({data,setData,onClose}:{data:AppData;setData:Store["setData"];onClose:()=>void}){const[reservationId,setReservationId]=useState(data.reservations[0]?.id??"");const[channel,setChannel]=useState<"En ligne"|"Carte à l’agence"|"Espèces à l’agence">("Carte à l’agence");const[amount,setAmount]=useState("");const r=data.reservations.find(x=>x.id===reservationId);const remaining=(r?.total??0)-(r?.paid??0);const save=()=>{const n=Number(amount);if(!r||n<=0||n>remaining){toast.error("Montant invalide",{description:`Le montant doit être compris entre 1 et ${money(remaining)}.`});return}const payment={id:`PAY-2026-${String(842+data.payments.length).padStart(5,"0")}`,reservationId:r.id,customerId:r.customerId,channel,amount:n,date:new Date().toISOString().slice(0,10),reference:`TF-${channel==="En ligne"?"ONL":channel==="Carte à l’agence"?"TPE":"CSH"}-${Date.now().toString().slice(-5)}`,agent:"Admin TiziFlow",status:"Validé"};setData(prev=>({...prev,payments:[payment,...prev.payments],reservations:prev.reservations.map(x=>x.id===r.id?{...x,paid:x.paid+n,paymentStatus:x.paid+n>=x.total?"Payé":"Partiellement payé"}:x)}));toast.success("Paiement enregistré");onClose()};return <Modal title="Enregistrer un paiement" onClose={onClose}><Label>Réservation</Label><Select value={reservationId} onValueChange={setReservationId}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent>{data.reservations.filter(x=>x.paid<x.total).map(x=><SelectItem value={x.id} key={x.id}>{x.id} · reste {money(x.total-x.paid)}</SelectItem>)}</SelectContent></Select><div className="drawer-summary"><div><small>Total</small><b>{money(r?.total??0)}</b></div><div><small>Payé</small><b>{money(r?.paid??0)}</b></div><div><small>Restant</small><b>{money(remaining)}</b></div></div><Label>Canal</Label><div className="payment-channels">{(["En ligne","Carte à l’agence","Espèces à l’agence"] as const).map(x=><Button key={x} variant={channel===x?"default":"outline"} onClick={()=>setChannel(x)}>{x}</Button>)}</div><Label>Montant</Label><Input type="number" min={1} max={remaining} value={amount} onChange={e=>setAmount(e.target.value)}/><div className="modal-actions"><Button variant="outline" onClick={onClose}>Annuler</Button><Button onClick={save}>Enregistrer</Button></div></Modal>}
function ProfileModal({data,role,setRole,reset,logout,onClose}:{data:AppData;role:Role;setRole:(r:Role)=>void;reset:()=>void;logout:()=>void;onClose:()=>void}){return <Modal title="Profil & agence" onClose={onClose}><div className="profile-heading"><img src={logo} alt="TiziFlow"/><div><Badge>Compte actif</Badge><h3>TiziFlow · Midelt</h3><p>admin@tiziflow.ma · MAD · GMT+1</p></div></div><Label>Simuler le rôle actif</Label><Select value={role} onValueChange={v=>setRole(v as Role)}><SelectTrigger><SelectValue/></SelectTrigger><SelectContent>{["Admin","Responsable","Guide","Fleet Manager"].map(x=><SelectItem key={x} value={x}>{x}</SelectItem>)}</SelectContent></Select><div className="settings-list"><div><div><b>Session sécurisée</b><p>Expiration après 8 heures d’inactivité.</p></div><Switch defaultChecked/></div><div><div><b>Authentification renforcée</b><p>Demander une confirmation pour les opérations sensibles.</p></div><Switch defaultChecked/></div></div><div className="profile-actions"><Button variant="outline" onClick={()=>{reset();toast.success("Données de démonstration restaurées")}}><RotateCcw/>Réinitialiser la démo</Button><Button variant="destructive" onClick={logout}><LogOut/>Se déconnecter</Button></div><small>{data.activity.length} événements conservés dans le journal.</small></Modal>}
